\begin{aligned}
\det A
&=\frac1{1000}
\begin{vmatrix}
23&40&42\\
29&36&-44\\
2&-6&-15
\end{vmatrix}\\
&=\frac1{1000}\left[23(-540-264)-40(-435+88)+42(-174-72)\right]\\
&=\frac{-14944}{1000}
=\boxed{-\frac{1868}{125}}.
\end{aligned}
\]

