\begin{array}{l}

\begin{array}{l}
 \text{Take the dot product of the following vectors}: \\
 \, (-2,-2)\, .\, (4,8)\,  \\
\end{array}
Step 2:
\begin{array}{l}
 \text{Multiply }\text{the }\text{row }\text{vector }\text{with }\text{the }\text{column }\text{vector}: \\
 \, (-2,-2)\, .\left(
\begin{array}{c}
 4 \\
 8 \\
\end{array}
